SELECT FuelSupport_PriceQ.Airport, ASMFuelT.VendorPrice AS ASM_BasePrice, ASMFuelT.Validity AS ASM_Validity, HadidFuelT.VendorPrice AS Hadid_BasePrice, HadidFuelT.Validity AS Hadid_Validity, ASMFuelT.EstimatedTotal AS ASM_EstimatedTotal, HadidFuelT.EstimatedTotal AS Hadid_EstimatedTotal, HadidFuelT.FlightType AS Hadid_FlightType, ASMFuelT.FlightType AS ASM_FlightType, AEGFuelT.VendorPrice AS AEG_BasePrice, AEGFuelT.Validity AS AEG_Validity, AEGFuelT.EstimatedTotal AS AEG_EstimatedTotal, UCIGFuelT.VendorPrice AS UCIG_BasePrice, UCIGFuelT.EstimatedTotal AS UCIG_EstimatedTotal, UCIGFuelT.FlightType AS UCIG_FlightType, UCIGFuelT.Validity AS UCIG_Validity, AEGFuelT.FlightType AS AEG_FlightType, LINKAEROFuelT.VendorPrice AS LINKAERO_BasePrice, LINKAEROFuelT.EstimatedTotal AS LINKAERO_EstimatedTotal, LINKAEROFuelT.FlightType AS LINKAERO_FlightType, LINKAEROFuelT.Validity AS LINKAERO_Validity, MASFuelT.VendorPrice AS MAS_BasePrice, MASFuelT.EstimatedTotal AS MAS_EstimatedTotal, MASFuelT.FlightType AS MAS_FlightType, MASFuelT.Validity AS MAS_Validity, FuelSupport_PriceQ.MinPrice, FuelSupport_PriceQ.TableName, FuelSupport_PriceQ.ID, FuelSupport_PriceQ.FlightType, FuelSupport_PriceQ.LOWCURRENCY, MixJetFuelT.VendorPrice AS MIXJET_BasePrice, MixJetFuelT.EstimatedTotal AS MIXJET_EstimatedTotal, MixJetFuelT.FlightType AS MIXJET_FlightType, MixJetFuelT.Validity AS MIXJET_Validity, AurroraFuelT.VendorPrice AS AUROR_BasePrice, AurroraFuelT.EstimatedTotal AS AUROR_EstimatedTotal, AurroraFuelT.FlightType AS AUROR_FlightType, AurroraFuelT.Validity AS AUROR_Validity, JetexFuelT.Validity AS JETEX_Validity, JetexFuelT.EstimatedTotal AS JETEX_EstimatedTotal, JetexFuelT.VendorPrice AS JETEX_BasePrice, JetexFuelT.FlightType AS JETEX_FlightType
FROM (AurroraFuelT RIGHT JOIN (MixJetFuelT RIGHT JOIN (AviaryFuelT RIGHT JOIN ((((((FuelSupport_PriceQ LEFT JOIN HadidFuelT ON (FuelSupport_PriceQ.FlightType = HadidFuelT.FlightType) AND (FuelSupport_PriceQ.Airport = HadidFuelT.Airport)) LEFT JOIN AEGFuelT ON (FuelSupport_PriceQ.FlightType = AEGFuelT.FlightType) AND (FuelSupport_PriceQ.Airport = AEGFuelT.Airport)) LEFT JOIN ASMFuelT ON (FuelSupport_PriceQ.FlightType = ASMFuelT.FlightType) AND (FuelSupport_PriceQ.Airport = ASMFuelT.Airport)) LEFT JOIN UCIGFuelT ON (FuelSupport_PriceQ.FlightType = UCIGFuelT.FlightType) AND (FuelSupport_PriceQ.Airport = UCIGFuelT.Airport)) LEFT JOIN MASFuelT ON (FuelSupport_PriceQ.FlightType = MASFuelT.FlightType) AND (FuelSupport_PriceQ.Airport = MASFuelT.Airport)) LEFT JOIN LINKAEROFuelT ON (FuelSupport_PriceQ.FlightType = LINKAEROFuelT.FlightType) AND (FuelSupport_PriceQ.Airport = LINKAEROFuelT.Airport)) ON (AviaryFuelT.FlightType = FuelSupport_PriceQ.FlightType) AND (AviaryFuelT.Airport = FuelSupport_PriceQ.Airport)) ON (MixJetFuelT.FlightType = FuelSupport_PriceQ.FlightType) AND (MixJetFuelT.Airport = FuelSupport_PriceQ.Airport)) ON (AurroraFuelT.FlightType = FuelSupport_PriceQ.FlightType) AND (AurroraFuelT.Airport = FuelSupport_PriceQ.Airport)) LEFT JOIN JetexFuelT ON (FuelSupport_PriceQ.FlightType = JetexFuelT.FlightType) AND (FuelSupport_PriceQ.Airport = JetexFuelT.Airport);
